def emitted_header_counters(header_lines: list[tuple[str, str]]) -> dict[str, Any]:
    """Counters for everything append_header_representation_rdf emits.

    ``header_lines`` is the ordered ``(key, value)`` list of '##' lines, without
    the leading '##' and split on the first '='.
    """
    classes: Counter[str] = Counter()
    predicates: Counter[str] = Counter()
    contigs = 0
    declarations: set[str] = set()

    for key, value in header_lines:
        key_lower = key.lower()
        structured = vocab.is_structured_header_value(value)
        line_class = HEADER_LINE_CLASSES.get(key_lower)
        if line_class is None:
            # An unrecognized key is still one of the two VCF forms. An
            # unstructured line is only typed when it has a value, because
            # vcfc:UnstructuredHeaderLineShape requires one.
            if structured:
                line_class = "StructuredHeaderLine"
            elif value:
                line_class = "UnstructuredHeaderLine"
            else:
                continue
        classes[line_class] += 1

        if not structured:
            if key_lower == "assembly" and value:
                predicates["assemblyUrl"] += 1
            elif key_lower == "pedigreedb" and value:
                predicates["pedigreeDbUrl"] += 1
            continue

        attributes = parse_structured_header_attributes(value)
        classes["HeaderAttribute"] += len(attributes)
        for name in ("hasAttribute", "attributeKey", "attributeValue", "attributeIndex"):
            predicates[name] += len(attributes)

        fields = dict(attributes)
        identifier = (fields.get("ID") or "").strip()

        if key_lower in {"info", "format"}:
            if not identifier:
                continue
            # An absent Description is synthesized, so the property is always
            # present on an INFO or FORMAT declaration.
            _count_field_definition(
                predicates, number=fields.get("Number") or ".",
                has_type=True, has_description=True,
            )
            if key_lower == "info":
                for attribute, predicate in vocab.INFO_EXTRA_ATTRIBUTES.items():
                    if fields.get(attribute):
                        predicates[predicate] += 1
        elif key_lower == "filter":
            if identifier:
                predicates["filterId"] += 1
                predicates["fieldDescription"] += 1
        elif key_lower == "alt":
            if identifier:
                predicates["altId"] += 1
                predicates["fieldDescription"] += 1
        elif key_lower == "contig":
            if not identifier:
                continue
            contigs += 1
            predicates["contigId"] += 1
            for attribute, (predicate, _datatype) in vocab.CONTIG_ATTRIBUTES.items():
                if fields.get(attribute):
                    predicates[predicate] += 1
        elif key_lower == "meta":
            if not identifier:
                continue
            _count_field_definition(
                predicates, number=fields.get("Number") or ".",
                has_type=True, has_description=fields.get("Description") is not None,
            )
            predicates["metaAllowedValue"] += len(_meta_values(fields.get("Values")))
        elif key_lower == "sample":
            if identifier:
                predicates["declaresSample"] += 1
                if identifier not in declarations:
                    declarations.add(identifier)
                    classes["SampleDeclaration"] += 1
        elif key_lower == "pedigree":
            for attribute_key, attribute_value in attributes:
                if attribute_key == "ID" or not attribute_value:
                    continue
                predicates[
                    vocab.PEDIGREE_ROLE_PROPERTIES.get(attribute_key, "pedigreeAncestor")
                ] += 1
                predicates["ancestorRole"] += 1
                if attribute_value not in declarations:
                    declarations.add(attribute_value)
                    classes["SampleDeclaration"] += 1

    if contigs:
        predicates["contigCount"] += 1
    return {
        "emittedHeaderClasses": dict(classes),
        "emittedHeaderPredicates": dict(predicates),
    }

def _count_sv_layer(
    classes: Counter, predicates: Counter, *, alleles: list, info_map: dict,
    pos: str, version: Any,
) -> None:
    """Count the SV carriers ``_emit_sv_layer`` attaches to a record's ALT alleles.

    Every condition is the emitter's: a carrier exists only when the record
    supplies what its shape needs. A repeated EVENT is one resource in the graph
    however many alleles name it, so events are counted as distinct triples.
    Tandem repeats are not modelled yet (see KNOWN_UNMODELLED in the tests).
    """
    alts = [allele for allele in alleles if allele.index >= 1]
    for key, predicate in vocab.SV_FLAG_INFO_KEYS.items():
        if key in info_map:
            predicates[predicate] += len(alts)
    for key, predicate in vocab.SV_ALLELE_INFO_KEYS.items():
        if info_map.get(key) is not None:
            predicates[predicate] += min(len(vocab.split_value_items(info_map[key])), len(alts))
    if info_map.get("SVCLAIM") is not None:
        claims = vocab.split_value_items(info_map["SVCLAIM"])[: len(alts)]
        predicates["svClaim"] += sum(
            1 for claim in claims if claim.strip().upper() in vocab.SV_CLAIMS
        )

    # gVCF reference blocks: END on a <*>/<NON_REF> allele.
    end = info_map.get("END")
    if end is not None and end.lstrip("-").isdigit():
        blocks = sum(1 for allele in alts if allele.kind == "UnspecifiedAllele")
        classes["ReferenceBlock"] += blocks
        predicates["endPosition"] += blocks
        predicates["isReferenceBlockStart"] += blocks
        if pos.isdigit():
            predicates["referenceBlockLength"] += blocks

    event, event_type = info_map.get("EVENT"), info_map.get("EVENTTYPE")
    if event and event_type and version.event_types:
        names = vocab.split_value_items(event)
        types = vocab.split_value_items(event_type)
        if not version.events_per_alt:
            names, types = names[:1], types[:1]
        events, typed, links = set(), set(), set()
        for offset, name in enumerate(names):
            code = types[offset] if offset < len(types) else None
            individual = vocab.EVENT_TYPES.get(code.strip().upper()) if code else None
            if vocab.is_missing(name) or individual is None:
                continue
            if version.events_per_alt and offset >= len(alts):
                continue
            events.add(name)
            typed.add((name, individual))
            links.add((offset + 1 if version.events_per_alt else 0, name))
        classes["VariantEvent"] += len(events)
        predicates["eventType"] += len(typed)
        predicates["inEvent"] += len(links)

    for key in (*vocab.FALDO_INTERVAL_INFO_KEYS, *vocab.CONFIDENCE_INTERVAL_INFO_KEYS):
        if info_map.get(key) is None or version.tuple_arity(key) is None:
            continue
        items = vocab.split_value_items(info_map[key])
        for offset in range(len(alts)):
            pair = offset if version.tuples_per_alt else 0
            if pair * 2 + 1 >= len(items):
                break
            if key in vocab.FALDO_INTERVAL_INFO_KEYS:
                predicates[vocab.FALDO_INTERVAL_INFO_KEYS[key]] += 1
                classes[FALDO_IN_RANGE_POSITION] += 1
                predicates[FALDO_BEGIN] += 1
                predicates[FALDO_END] += 1
            else:
                predicates[vocab.CONFIDENCE_INTERVAL_INFO_KEYS[key]] += 1
                classes["ConfidenceInterval"] += 1
                predicates["ciLower"] += 1
                predicates["ciUpper"] += 1

