PREFIX sg: <https://sparqling-genomics.org/0.99.11/>
PREFIX vc: <sg://0.99.11/vcf2rdf/>
PREFIX v: <sg://0.99.11/vcf2rdf/variant/>
PREFIX gt: <sg://0.99.11/vcf2rdf/format/GT/>
PREFIX hdr: <sg://0.99.11/vcf2rdf/header/>
PREFIX faldo: <http://biohackathon.org/resource/faldo#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
# SPARQLing Genomics vcf2rdf 0.99.11, default options. It writes one vc:VariantCall per record and
# sample, and only for calls with a non-reference allele; there is no record node. Call IRIs are
# origin://<md5>@<k> with k = record index x samples + sample index (doc/command-line-tools.tex),
# so records are regrouped on floor(k / samples). Only the first ALT allele is written.
# INFO, FORMAT, FILTER, contig and ALT definitions are typed items; a simple ##key=value line is
# hdr:<key> hdr:<key> "value". A structured line with any other key loses that key.
SELECT ?headerKey (COUNT(DISTINCT ?item) AS ?lineCount)
WHERE {
  { ?item a vc:InfoItem BIND("INFO" AS ?headerKey) }
  UNION { ?item a vc:FormatItem BIND("FORMAT" AS ?headerKey) }
  UNION { ?item a vc:FilterItem BIND("FILTER" AS ?headerKey) }
  UNION { ?item a vc:ContigItem BIND("contig" AS ?headerKey) }
  UNION { ?item a vc:AltItem BIND("ALT" AS ?headerKey) }
  UNION { ?headerItem a vc:HeaderItem ; ?predicate ?item FILTER(?predicate = ?headerItem)
          BIND(STRAFTER(STR(?headerItem), "sg://0.99.11/vcf2rdf/header/") AS ?headerKey) }
}
GROUP BY ?headerKey
ORDER BY ?headerKey

PREFIX g: <https://www.codamono.com/gfvo-squared#>
PREFIX gu: <https://www.codamono.com/gfvo-squared#unknownProperty->
PREFIX gc: <https://github.com/BioInterchange/Ontologies/gfvo-squared#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
# BioInterchange 2.0.5: GFVO-squared JSON-LD, one gc:Feature (a blank node) per record, with the
# header on a gc:Meta node. ALT alleles are g:alleleB, g:alleleC, ... in file order; "*" is
# written as "".
# Simple lines are properties of gc:Meta; FILTER, FORMAT and contig definitions are members of
# a bag each; INFO and ALT share one bag (g:alleleFormat) and are told apart by whether the
# definition has a g:type; unknown keys are under g:userDefined.
SELECT ?headerKey (COUNT(DISTINCT ?item) AS ?lineCount)
WHERE {
  ?meta a gc:Meta .
  {
    VALUES (?property ?headerKey) {
      (g:vcfVersion "fileformat") (g:fileDate "fileDate") (g:referenceFASTA "reference")
      (g:source "source") (g:breakpointFASTA "assembly") (gu:phasing "phasing")
    }
    ?meta ?property ?item .
  } UNION {
    VALUES (?property ?headerKey) {
      (g:annotationFormat "FILTER") (g:genotypeFormat "FORMAT") (g:contig "contig")
      (gu:sample "SAMPLE") (gu:pedigree "PEDIGREE")
    }
    ?meta ?property ?bag . ?bag ?item ?definition .
  } UNION {
    ?meta g:alleleFormat ?bag . ?bag ?item ?definition . ?definition g:type ?type .
    BIND("INFO" AS ?headerKey)
  } UNION {
    ?meta g:alleleFormat ?bag . ?bag ?item ?definition .
    FILTER NOT EXISTS { ?definition g:type ?type }
    BIND("ALT" AS ?headerKey)
  } UNION {
    ?meta g:userDefined ?userDefined . ?userDefined ?property ?item .
    BIND(STRAFTER(STR(?property), "#unknownProperty-") AS ?headerKey)
  }
}
GROUP BY ?headerKey
ORDER BY ?headerKey

