ref = v.REF;  alt = ",".join("." if a is None else a for a in (v.ALT or [None]))   # cyvcf2 arms
# bcftools arm: ref, alt = the %REF and %ALT columns of 'bcftools query -r ... -f %CHROM\t%POS\t%REF\t%ALT'
ref, alt = ref.upper(), alt.upper()
cls = ("NO_ALT" if alt == "." else "MULTIALLELIC" if "," in alt
       else "SYMBOLIC_OR_BREAKEND" if alt == "*" or "[" in alt or "]" in alt or (alt.startswith("<") and alt.endswith(">"))
       else "OTHER" if not fullmatch("[ACGTN]+", ref) or not fullmatch("[ACGTN]+", alt)
       else "SNV" if len(ref) == len(alt) == 1
       else "MNV_OR_EQUAL_LENGTH_SUBSTITUTION" if len(ref) == len(alt)
       else "INSERTION_SHAPE" if len(ref) < len(alt) else "DELETION_SHAPE")
shapes[cls] += 1
return [{"variantClass": c, "recordCount": n} for c, n in sorted(shapes.items())]

